use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input["text"].as_str().unwrap();
    let shift = input["shift"].as_u64().unwrap();
    let text = text.to_string();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_lowercase() {
            let base = c.to_lowercase().next().unwrap() as u8;
            let new_base = (base as u8 + shift) % 26;
            result.push((new_base as char).to_string());
        } else {
            result.push(c);
        }
    }
    Value::String(result)
}
